include <robotics.scad>
// Origin: board centre, bottom face. X = connector edge (25), Y = 23.862, connector edge at +Y.
W = 25; D = 23.862; T = 1.0;      // T not dimensioned
r_c = 2.0; hole_d = 2.2;
hy0 = -D/2 + 2; hy1 = -D/2 + 14.5;  // from edge opposite the connector
diff() cuboid([W, D, T], rounding = r_c, edges = "Z", anchor = BOT, $fn = 48) {
  tag("remove") for (x = [-10.5, 10.5], y = [hy0, hy1])
    translate([x, y, 0]) cyl(d = hole_d, h = T + 1, $fn = 40);
}

